e\":\"uint128\"}],\"stateMutability\":\"payable\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"tradingFeePPM\",\"outputs\":[{\"internalType\":\"uint32\",\"name\":\"\",\"type\":\"uint32\"}],\"stateMutability\":\"view\",\"type\":\"function\"},{\"inputs\":[{\"internalType\":\"uint256\",\"name\":\"strategyId\",\"type\":\"uint256\"},{\"components\":[{\"internalType\":\"uint128\",\"name\":\"y\",\"type\":\"uint128\"},{\"internalType\":\"uint128\",\"name\":\"z\",\"type\":\"uint128\"},{\"internalType\":\"uint64\",\"name\":\"A\",\"type\":\"uint64\"},{\"internalType\":\"uint64\",\"name\":\"B\",\"type\":\"uint64\"}],\"internalType\":\"struct Order[2]\",\"name\":\"currentOrders\",\"type\":\"tuple[2]\"},{\"components\":[{\"internalType\":\"uint128\",\"name\":\"y\",\"type\":\"uint128\"},{\"internalType\":\"uint128\",\"name\":\"z\",\"type\":\"uint128\"},{\"internalType\":\"uint64\",\"name\":\"A\",\"type\":\"uint64\"},{\"internalType\":\"uint64\",\"name\":\"B\",\"type\":\"uint64\"}],\"internalType\":\"struct Order[2]\",\"name\":\"newOrders\",\"type\":\"tuple[2]\"}],\"name\":\"updateStrategy\",\"outputs\":[],\"stateMutability\":\"payable\",\"type\":\"function\"},{\"inputs\":[],\"name\":\"version\",\"outputs\":[{\"internalType\":\"uint16\",\"name\":\"\",\"type\":\"uint16\"}],\"stateMutability\":\"pure\",\"type\":\"function\"},{\"inputs\":[{\"internalType\":\"Token\",\"name\":\"token\",\"type\":\"address\"},{\"internalType\":\"uint256\",\"name\":\"amount\",\"type\":\"uint256\"},{\"internalType\":\"address\",\"name\":\"recipient\",\"type\":\"address\"}],\"name\":\"withdrawFees\",\"outputs\":[{\"internalType\":\"uint256\",\"name\":\"\",\"type\":\"uint256\"}],\"stateMutability\":\"nonpayable\",\"type\":\"function\"}],\"devdoc\":{\"details\":\"Carbon Controller contract\",\"events\":{\"FeesWithdrawn(address,address,uint256,address)\":{\"details\":\"triggered when fees are withdrawn\"},\"Initialized(uint8)\":{\"details\":\"Triggered when the contract has been initialized or reinitialized.\"},\"PairCreated(uint128,address,address)\":{\"details\":\"triggered when a new pair is created\"},\"PairTradingFeePPMUpdated(address,address,uint32,uint32)\":{\"details\":\"triggered when the custom trading fee for a given pair is updated\"},\"RoleAdminChanged(bytes32,bytes32,bytes32)\":{\"details\":\"Emitted when `newAdminRole` is set as ``role``'s admin role, replacing `previousAdminRole` `DEFAULT_ADMIN_ROLE` is the starting admin for all roles, despite {RoleAdminChanged} not being emitted signaling this. _Available since v3.1._\"},\"RoleGranted(bytes32,address,address)\":{\"details\":\"Emitted when `account` is granted `role`. `sender` is the account that originated the contract call, an admin role bearer except when using {AccessControl-_setupRole}.\"},\"RoleRevoked(bytes32,address,address)\":{\"details\":\"Emitted when `account` is revoked `role`. `sender` is the account that originated the contract call:   - if using `revokeRole`, it is the admin role bearer   - if using `renounceRole`, it is the role bearer (i.e. `account`)\"},\"StrategyCreated(uint256,address,address,address,(uint128,uint128,uint64,uint64),(uint128,uint128,uint64,uint64))\":{\"details\":\"triggered when a strategy is created\"},\"StrategyDeleted(uint256,address,address,address,(uint128,uint128,uint64,uint64),(uint128,uint128,uint64,uint64))\":{\"details\":\"triggered when a strategy is deleted\"},\"StrategyUpdated(uint256,address,address,(uint128,uint128,uint64,uint64),(uint128,uint128,uint64,uint64),uint8)\":{\"details\":\"triggered when a strategy is updated\"},\"TokensTraded(address,address,address,uint256,uint256,uint128,bool)\":{\"details\":\"triggered when tokens are traded\"},\"TradingFeePPMUpdated(uint32,uint32)\":{\"details\":\"triggered when the network fee is updated\"}},\"kind\":\"dev\",\"methods\":{\"accumulatedFees(address)\":{\"details\":\"returns the amount of fees accumulated for the specified token\"},\"calculateTradeSourceAmount(address,address,(uint256,uint128)[])\":{\"details\":\"returns the source amount required when trading by target amount\"},\"calculateTradeTargetAmount(address,address,(uint256,uint128)[])\":{\"details\":\"returns the target amount expected when trading by source amount\"},\"constructor\":{\"details\":\"used to set immutable state variables and initialize the implementation\"},\"controllerType()\":{\"details\":\"returns the type of the controller\"},\"createPair(address,address)\":{\"details\":\"creates a new pair of provided token0 and token1\"},\"createStrategy(address,address,(uint128,uint128,uint64,uint64)[2])\":{\"details\":\"creates a new strategy, returns the strategy's id requirements: - the caller must have approved the tokens with assigned liquidity in the order, if any\"},\"deleteStrategy(uint256)\":{\"details\":\"deletes a strategy matching the provided id notes: - 100% of liquidity is withdrawn and sent to the owner requirements: - the caller must be the owner of the NFT voucher\"},\"getRoleAdmin(bytes32)\":{\"details\":\"Returns the admin role that controls `role`. See {grantRole} and {revokeRole}. To change a role's admin, use {_setRoleAdmin}.\"},\"getRoleMember(bytes32,uint256)\":{\"details\":\"Returns one of the accounts that have `role`. `index` must be a value between 0 and {getRoleMemberCount}, non-inclusive. Role bearers are not sorted in any particular way, and their ordering may change at any point. WARNING: When using {getRoleMember} and {getRoleMemberCount}, make sure you perform all queries on the same block. See the following https://forum.openzeppelin.com/t/iterating-over-elements-on-enumerableset-in-openzeppelin-contracts/2296[forum post] for more information.\"},\"getRoleMemberCount(bytes32)\":{\"details\":\"Returns the number of accounts that have `role`. Can be used together with {getRoleMember} to enumerate all bearers of a role.\"},\"grantRole(bytes32,address)\":{\"details\":\"Grants `role` to `account`. If `account` had not been already granted `role`, emits a {RoleGranted} event. Requirements: - the caller must have ``role``'s admin role. May emit a {RoleGranted} event.\"},\"hasRole(bytes32,address)\":{\"details\":\"Returns `true` if `account` has been granted `role`.\"},\"initialize()\":{\"details\":\"fully initializes the contract and its parents\"},\"pair(address,address)\":{\"details\":\"returns a pair's metadata matching the provided token0 and token1\"},\"pairTradingFeePPM(address,address)\":{\"details\":\"returns the trading fee for a given pair (in units of PPM)\"},\"pairs()\":{\"details\":\"returns a list of all supported pairs\"},\"postUpgrade(bytes)\":{\"details\":\"performs post-upgrade initialization requirements: - this must and can be called only once per-upgrade\"},\"renounceRole(bytes32,address)\":{\"details\":\"Revokes `role` from the calling account. Roles are often managed via {grantRole} and {revokeRole}: this function's purpose is to provide a mechanism for accounts to lose their privileges if they are compromised (such as when a trusted device is misplaced). If the calling account had been revoked `role`, emits a {RoleRevoked} event. Requirements: - the caller must be `account`. May emit a {RoleRevoked} event.\"},\"revokeRole(bytes32,address)\":{\"details\":\"Revokes `role` from `account`. If `account` had been granted `role`, emits a {RoleRevoked} event. Requirements: - the caller must have ``role``'s admin role. May emit a {RoleRevoked} event.\"},\"roleAdmin()\":{\"details\":\"returns the admin role\"},\"roleFeesManager()\":{\"details\":\"returns the fees manager role\"},\"setPairTradingFeePPM(address,address,uint32)\":{\"details\":\"sets the custom trading fee for a given pair (in units of PPM) requirements: - the caller must be the admin of the contract\"},\"setTradingFeePPM(uint32)\":{\"details\":\"sets the trading fee (in units of PPM) requirements: - the caller must be the admin of the contract\"},\"strategiesByPair(address,address,uint256,uint256)\":{\"details\":\"returns strategies belonging to a specific pair note that for the full list of strategies pass 0 to both startIndex and endIndex\"},\"strategiesByPairCount(address,address)\":{\"details\":\"returns the count of strategies belonging to a specific pair\"},\"strategy(uint256)\":{\"details\":\"returns a strategy matching the provided id, note tokens and orders are returned sorted as provided upon creation\"},\"supportsInterface(bytes4)\":{\"details\":\"See {IERC165-supportsInterface}.\"},\"tradeBySourceAmount(address,address,(uint256,uint128)[],uint256,uint128)\":{\"details\":\"performs a trade by specifying a fixed source amount notes: - excess native token is returned to the sender if any requirements: - the caller must have approved the source token\"},\"tradeByTargetAmount(address,address,(uint256,uint128)[],uint256,uint128)\":{\"details\":\"performs a trade by specifying a fixed target amount notes: - excess native token is returned to the sender if any requirements: - the caller must have approved the source token\"},\"tradingFeePPM()\":{\"details\":\"returns the trading fee (in units of PPM)\"},\"updateStrategy(uint256,(uint128,uint128,uint64,uint64)[2],(uint128,uint128,uint64,uint64)[2])\":{\"details\":\"updates an existing strategy notes: - currentOrders should reflect the orders values at the time of sending the tx this prevents cases in which the strategy was updated due to a trade between the time the transaction was sent and the time it was mined, thus, giving more control to the strategy owner. - reduced liquidity is refunded to the owner - increased liquidity is deposited - excess native token is returned to the sender if any - the sorting of orders is expected to equal the sorting upon creation requirements: - the caller must have approved the tokens with increased liquidity, if any\"},\"withdrawFees(address,uint256,address)\":{\"details\":\"transfers the accumulated fees to the specified recipient notes: `amount` is capped to the available amount returns the amount withdrawn\"}},\"version\